describe('Hydro Cannon mob skill',function()
 it('uses level-dependent Water breath caps, then gated Poison and cleanup',function()
  local cannon=require('scripts/actions/mobskills/hydro_cannon');local move,process,effect=xi.mobskills.mobBreathMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove;local params,damage,poison,deleted,localVar=nil,nil,nil,nil,nil;local level=64;local mob={getMainLvl=function()return level end,setLocalVar=function(_,key,value)localVar={key,value}end};local resistance=true;local target={takeDamage=function(_,...)damage={...}end,hasStatusEffect=function(_,id)return resistance and id==xi.effect.ELEMENTALRES_DOWN end,delStatusEffectSilent=function(_,id)deleted=id end};xi.mobskills.mobBreathMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.BREATH,damageType=xi.damageType.WATER}end;xi.mobskills.processDamage=function()return false end;xi.mobskills.mobStatusEffectMove=function(_,_,...)poison={...}end
  assert(cannon.onMobSkillCheck(target,mob,{})==0 and cannon.onMobWeaponSkill(mob,target,{},{})==123);assert(params.percentMultipier==.05 and params.damageCap==490 and params.bonusDamage==0 and params.mAccuracyBonus[1]==0 and params.mAccuracyBonus[2]==0 and params.mAccuracyBonus[3]==0 and params.resistStat==xi.mod.INT and params.element==xi.element.WATER and params.attackType==xi.attackType.BREATH and params.damageType==xi.damageType.WATER and params.shadowBehavior==xi.mobskills.shadowBehavior.IGNORE_SHADOWS and damage==nil and poison==nil and deleted==nil and localVar[1]=='nuclearWaste' and localVar[2]==0);level=65;cannon.onMobWeaponSkill(mob,target,{},{});assert(params.damageCap==750);xi.mobskills.processDamage=function()return true end;cannon.onMobWeaponSkill(mob,target,{},{})
  xi.mobskills.mobBreathMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove=move,process,effect;assert(damage[1]==123 and damage[2]==mob and damage[3]==xi.attackType.BREATH and damage[4]==xi.damageType.WATER);assert(poison[1]==xi.effect.POISON and poison[2]==50 and poison[3]==3 and poison[4]==120 and deleted==xi.effect.ELEMENTALRES_DOWN)
 end)
